def fetch_contacts_for_name(name, relationship=None):
    page_index=0
    page_limit=20
    allc=[]
    while True:
        kwargs={'access_token': phone_access_token, 'query': name, 'page_index': page_index, 'page_limit': page_limit}
        if relationship is not None:
            kwargs['relationship']=relationship
        page = apis.phone.search_contacts(**kwargs)
        print('contact search', name, 'relationship', relationship, 'page', page_index, 'count', len(page) if page else 0)
        if not page:
            break
        allc.extend(page)
        page_index += 1
        if page_index>50:
            break
    return allc

contact_email_map = {}
ambiguous = {}
missing = []

for person,_ in owes_me + i_owe:
    # first try friends relationship
    contacts = fetch_contacts_for_name(person, relationship='friend')
    if len(contacts)==0:
        contacts = fetch_contacts_for_name(person, relationship=None)
    # pick matches: try exact first_name match
    exact = [c for c in contacts if c.get('first_name','').lower()==person.lower()]
    if len(exact)==1:
        chosen=exact[0]
    elif len(contacts)==1:
        chosen=contacts[0]
    elif len(exact)>1:
        ambiguous[person]=[{'first_name':c.get('first_name'), 'last_name':c.get('last_name'), 'email':c.get('email')} for c in exact]
        continue
    else:
        if len(contacts)>0:
            # if multiple and no exact-first match, mark ambiguous
            if len(contacts)>1:
                ambiguous[person]=[{'first_name':c.get('first_name'), 'last_name':c.get('last_name'), 'email':c.get('email')} for c in contacts]
                continue
            chosen=contacts[0]
        else:
            missing.append(person)
            continue
    email = chosen.get('email')
    contact_email_map[person]=email

print('contact_email_map', contact_email_map)
